from reportlab.lib import colors
from reportlab.lib.pagesizes import A4
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib.units import mm
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, PageBreak

NAVY=colors.HexColor('#102A43'); BLUE=colors.HexColor('#1677B8'); TEAL=colors.HexColor('#087A73')
PALE=colors.HexColor('#EAF4FA'); LIGHT=colors.HexColor('#F5F8FA'); GRID=colors.HexColor('#C9D4DF'); TEXT=colors.HexColor('#243B53')
W,H=A4
s=getSampleStyleSheet()
s.add(ParagraphStyle(name='K',parent=s['Normal'],fontName='Helvetica-Bold',fontSize=9,leading=12,textColor=TEAL,spaceAfter=9))
s.add(ParagraphStyle(name='T',parent=s['Title'],fontName='Helvetica-Bold',fontSize=24,leading=29,textColor=NAVY,spaceAfter=8))
s.add(ParagraphStyle(name='H',parent=s['Heading1'],fontName='Helvetica-Bold',fontSize=16,leading=20,textColor=NAVY,spaceBefore=11,spaceAfter=6))
s.add(ParagraphStyle(name='B',parent=s['BodyText'],fontName='Helvetica',fontSize=9.1,leading=13,textColor=TEXT,spaceAfter=5))
s.add(ParagraphStyle(name='C',parent=s['BodyText'],fontName='Helvetica-Bold',fontSize=10,leading=14,textColor=NAVY,backColor=PALE,borderColor=colors.HexColor('#B7D8EC'),borderWidth=.5,borderPadding=9,spaceAfter=9))
s.add(ParagraphStyle(name='TH',parent=s['BodyText'],fontName='Helvetica-Bold',fontSize=7.5,leading=9.3,textColor=colors.white))
s.add(ParagraphStyle(name='TC',parent=s['BodyText'],fontName='Helvetica',fontSize=7.45,leading=9.3,textColor=TEXT))

def p(t,st='B'): return Paragraph(t,s[st])
def bullets(xs): return [p('&bull; '+x) for x in xs]
def tbl(h, rows, widths):
    d=[[p(x,'TH') for x in h]]+[[p(x,'TC') for x in r] for r in rows]
    t=Table(d,colWidths=widths,repeatRows=1,hAlign='LEFT')
    t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),NAVY),('GRID',(0,0),(-1,-1),.35,GRID),('VALIGN',(0,0),(-1,-1),'TOP'),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,LIGHT]),('LEFTPADDING',(0,0),(-1,-1),5),('RIGHTPADDING',(0,0),(-1,-1),5),('TOPPADDING',(0,0),(-1,-1),4),('BOTTOMPADDING',(0,0),(-1,-1),4)]))
    return t
def foot(c,d):
    c.saveState(); c.setStrokeColor(GRID); c.line(18*mm,14*mm,W-18*mm,14*mm); c.setFillColor(TEXT); c.setFont('Helvetica',7.5)
    c.drawString(18*mm,9*mm,'Solar Power Generation Prediction - Revised Hackathon Package'); c.drawRightString(W-18*mm,9*mm,'Page %d'%d.page); c.restoreState()
def make(path,title,frame,parts):
    st=[p('REVISED HACKATHON PREPARATION PACKAGE','K'),p(title,'T'),p(frame,'C'),Spacer(1,3)]
    for kind,body in parts:
        if kind=='page': st.append(PageBreak())
        elif kind=='h': st.append(p(body,'H'))
        elif kind=='p': st.append(p(body))
        elif kind=='b': st.extend(bullets(body))
        elif kind=='t': st.append(tbl(*body))
    SimpleDocTemplate(path,pagesize=A4,leftMargin=18*mm,rightMargin=18*mm,topMargin=16*mm,bottomMargin=20*mm,title=title,author='Codex').build(st,onFirstPage=foot,onLaterPages=foot)

analysis=[
('h','Purpose'),('p','Define a realistic, evidence-led MVP that estimates expected solar output and identifies intervals that deserve review. The supplied files contain generation readings by inverter and weather readings by plant. The product must quantify prediction quality on future time and must not call a deviation an equipment fault without supporting evidence.'),
('h','What the statement is actually asking'),('b',['Benchmark Linear Regression, Random Forest Regressor and SVR with MAE, RMSE and R-squared on a genuinely unseen chronological test period.','Explain large prediction residuals with timestamp, weather, reporting coverage and raw context.','Provide a monitoring dashboard, not just a notebook.','Make a defensible level-of-analysis decision. This MVP uses plant-level mean AC power per reporting inverter because it is less sensitive to missing inverter reports.']),
('h','Core product promise - decision loop'),('p','Ingest -> normalize time -> compute plant interval mean AC power and n_reporting -> join weather -> build leakage-safe features -> predict expected mean AC power -> calculate residual -> apply a validation-calibrated daylight rule -> show context -> invite human investigation. A small per-inverter evidence table is optional support, not the primary model.'),
('h','Required capabilities'),('t',(['Capability','MVP decision'],[['Time-safe data prep','Parse mixed timestamps. At each plant and 15-minute interval calculate mean AC_POWER across reporting inverters and n_reporting.'],['Model benchmark','Use 70/15/15 chronological split: earliest 70 percent train, next 15 percent validation, final 15 percent untouched test.'],['Deviation detection','Calibrate robust residual scale on validation residuals only. Freeze rule before scoring test. Gate out non-daylight intervals.'],['Event context','Show actual mean AC, expected mean AC, residual, validation-calibrated band, n_reporting, weather and timestamp.'],['Dashboard','Streamlit only: filters, metrics, actual-vs-expected, residual bands, coverage and event drilldown.']],[35*mm,129*mm])),
('page',''),('h','Reference architecture'),('p','Supplied CSVs -> validation and 15-minute aggregation -> plant interval feature table -> chronological split -> three sklearn pipelines -> validation selection/calibration -> one-time test score -> saved metrics, predictions and events -> Streamlit dashboard. This deterministic local path is deliberately sufficient for the hackathon.'),
('h','Recommended hackathon technology stack'),('t',(['Layer','Choice','Why'],[['Data and ML','Python, pandas, scikit-learn, joblib','Fast, reproducible processing and the three requested regressors.'],['UI','Streamlit and Plotly','One process, rapid filters and interactive time-series without an API server.'],['Persistence','CSV artifacts; optional local JSON only','Enough for metrics, predictions and optional review notes. Do not make review workflow a critical path.'],['Quality','pytest and explicit data-quality counters','Tests time alignment, coverage, leakage and alert logic.'],['Packaging','requirements.txt, README, one run command','Lets judges repeat the walkthrough.']],[31*mm,47*mm,86*mm])),
('h','Core data model'),('t',(['Entity','Key fields'],[['WeatherObservation','plant_id, timestamp, ambient_temperature, module_temperature, irradiation_value (unit not documented)'],['PlantInterval','plant_id, timestamp, mean_ac_power, n_reporting, reporting_coverage flag'],['FeatureRow','irradiation_value, ambient_temperature, module_temperature, hour_sin, hour_cos, daylight_eligible; no DC, yield or lagged actual output'],['Prediction','plant_id, timestamp, model_version, actual_mean_ac, predicted_mean_ac, residual, band_width, n_reporting'],['DeviationEvent','timestamp, direction, residual, threshold, daylight status, n_reporting, weather context; optional severity/review note']],[42*mm,122*mm])),
('h','Important technical and product decisions'),('b',['Use mean AC power per reporting inverter as the target. Summed AC can create a false drop when Plant 2 has missing inverter reports. Always surface n_reporting.', 'Do not use DC_POWER, DAILY_YIELD, TOTAL_YIELD or lagged actual output as model features. DC has a substantially different scale, yield may be unavailable at prediction time, and lags can hide the deviation being sought.', 'Use irradiation_value, not W/m2: the source unit is not documented.','Use hour sine/cosine. Do not use day-of-year by default because this dataset spans roughly one month; if tried, compare it explicitly against the simpler feature set on validation.', 'Random Forest, linear regression and SVR should use the same feature contract. Standardize features for linear/SVR pipelines; do not claim a native model confidence interval.']),
('page',''),('h','Deviation policy and explainability'),('p','Choose the champion on validation metrics, then calibrate its alert band from validation residuals, for example a robust median absolute deviation scale with a documented k. The dashboard shows predicted mean AC plus or minus k times the validation-derived robust scale - a residual tolerance band, not a model confidence interval. Apply the frozen band once to the final test period.'),
('h','Judge-friendly success criteria'),('t',(['Area','Evidence'],[['Predictive integrity','MAE, RMSE and R-squared for all three models on the same final unseen period; champion was selected before that score.'],['Coverage integrity','Every chart and event exposes n_reporting. A low count is a data-coverage concern, not automatic poor solar performance.'],['Actionability','A flagged interval exposes actual, expected, residual, calibrated band, irradiation_value, temperatures and timestamp.'],['Honesty','Copy says deviation or investigation candidate. A compact inverter table may support peer evidence, but no fault claim is automated.'],['Demo clarity','Judge can select Plant 1 or Plant 2, inspect coverage and drill into an alert within one minute.']],[42*mm,122*mm])),
('h','Suggested 3-5 minute demo flow'),('b',['Frame the question: expected mean AC output given weather, time and reporting coverage.','Show 70/15/15 chronology, model comparison and validation-based champion selection.','Open unseen test results: actual versus expected with the tolerance band.','Inspect one deviation and its n_reporting, irradiation_value and temperatures.','Optionally show peer inverter evidence, then state the limitation: it supports investigation, not a fault conclusion.']),
('h','Scope boundaries and definition of done'),('p','MVP: two-plant CSV batch workflow, plant-level mean target, coverage-aware residual alerts and a local Streamlit dashboard. Stretch: richer inverter drilldown, optional review status, severity or local notes. Production is out of scope: live SCADA, FastAPI, authentication, ticketing and automated fault decisions. Done means a documented clean run trains all three models, saves chronological metrics/predictions, renders the dashboard, exposes coverage and limitations, and passes core tests.')]

prd=[
('h','Product goal'),('p','Help an analyst compare observed mean AC power per reporting inverter with an expected value on future time periods, while distinguishing potential performance deviations from missing-reporting artifacts. Solar Lens is a triage tool, not a fault-diagnosis system.'),
('h','Product scope'),('t',(['In scope','Out of scope'],[['15-minute plant-level mean AC target and n_reporting for both plants.','Automatically identifying a component failure or root cause.'],['Linear, Random Forest and SVR evaluated with one chronological 70/15/15 sequence.','Random shuffling, selecting a winner on final test, or live streaming.'],['Validation-derived residual tolerance band and daylight eligibility.','FastAPI, cloud deployment, authentication or work-order integration.'],['Local Streamlit dashboard with coverage-aware drilldown.','Mandatory review workflow, SQLite, severity workflows or ticketing.']],[82*mm,82*mm])),
('h','Personas and needs'),('t',(['Persona','Need','MVP response'],[['Operations analyst','Know if plant behavior differs materially from expectation.','Actual-vs-expected chart and residual band for unseen dates.'],['Site engineer','Avoid spending time on missing-data artifacts.','n_reporting and weather context displayed with every candidate.'],['Hackathon judge','Verify rigor and usefulness rapidly.','Chronological split, three-model metrics, calibration logic and drilldown.']],[32*mm,52*mm,80*mm])),
('h','Functional requirements'),('b',['FR-1 Parse generation and weather CSVs, report malformed rows and normalize timestamps.','FR-2 Compute plant mean AC_POWER and n_reporting for every timestamp; join same-plant weather.','FR-3 Build features from irradiation_value (unit not documented), ambient/module temperature and hour cyclic features. Exclude DC, yield, lagged actual output and default day-of-year.','FR-4 Train Linear Regression, Random Forest and SVR using train data; choose champion on validation only; score final test once.','FR-5 Calibrate the robust residual tolerance band from validation residuals and apply daylight gating.','FR-6 Render Streamlit filters, metric table, trends, residual band, coverage and deviation table.','FR-7 Optionally expose a small peer-inverter table for selected intervals; do not make fault statements.']),
('h','Non-functional requirements'),('b',['Reproducible: fixed seed, saved split boundaries, feature contract, model artifact and calibration artifact.','Transparent: display target definition, n_reporting, unit caveat and threshold method.','Responsive: selected dashboard view responds locally in under 3 seconds on supplied files.','Robust: missing weather produces an explicit coverage state, not silent imputation.']),
('h','End-to-end user journey'),('p','1. Open Streamlit. 2. Select plant and test date range. 3. Confirm coverage and selected champion. 4. Inspect actual mean AC versus expected mean AC and tolerance band. 5. Filter deviation candidates. 6. Open one interval to see residual, n_reporting, irradiation_value and temperatures. 7. Optionally inspect reporting inverter peers. 8. Treat output as an investigation lead only.'),
('h','Internal data/service contracts - no MVP network API'),('t',(['Contract','Input','Output'],[['build_intervals','Raw generation and weather files','PlantInterval rows with mean_ac_power, n_reporting and weather join quality.'],['build_features','Eligible PlantInterval rows','Feature rows without yield, DC or actual-output lag.'],['train_benchmark','Chronological train/validation rows','Three fitted pipelines, validation metrics and champion.'],['calibrate_band','Champion validation residuals','Robust band width, k, daylight rule and calibration period.'],['score_test','Frozen model, features and band','One-time test metrics, prediction rows and deviation candidates.'],['render_dashboard','Saved artifacts and selected filters','Charts, metrics, coverage context and optional peer evidence.']],[37*mm,54*mm,73*mm])),
('h','UI/dashboard requirements'),('p','Include plant/date filters; a transparent target-definition note; quality cards for champion, test MAE/RMSE/R-squared and weather coverage; a model comparison table; actual versus expected mean AC chart; residual chart with validation-derived tolerance band; n_reporting trend or badge; and an event table with neutral labels. Optional: selected interval peer-inverter mini-table. Do not expose a fake confidence interval or use units for irradiation that the source does not document.'),
('h','Acceptance criteria'),('t',(['ID','Acceptance check'],[['AC-1','Joined intervals report mean AC, n_reporting, weather coverage and malformed/unmatched-row counts.'],['AC-2','All three models report MAE, RMSE and R-squared on identical final test rows.'],['AC-3','Champion selection and tolerance calibration use validation only; final test is untouched until scoring.'],['AC-4','Each test event includes n_reporting, actual/expected mean AC, residual, frozen band and weather context.'],['AC-5','No model feature includes DC, yield or lagged actual output. Irradiation label states unit not documented.'],['AC-6','Streamlit demo runs locally without FastAPI; optional review/severity features do not block demo.']],[25*mm,139*mm])),
('page',''),('h','MVP versus stretch goals'),('t',(['MVP','Stretch - only after core demo'],[['Streamlit-only local dashboard; saved CSV/joblib artifacts.','Peer-inverter evidence table, optional review note or local severity label.'],['Plant mean AC per reporting inverter and n_reporting.','Compare alternate aggregation or separate inverter diagnostic model.'],['Validation-calibrated robust band and daylight gate.','Time-series cross-validation, conditional bands and drift checks.'],['Hour cyclic features and documented unit caveat.','Explicit validation comparison of day-of-year or other feature candidates.']],[82*mm,82*mm])),
('h','Hackathon demo success criteria'),('p','The demo proves a decision chain: raw inputs -> coverage-aware plant interval -> leakage-safe benchmark -> validation-selected champion -> validation-calibrated tolerance band -> final unseen test -> human-reviewable deviation. It clearly names Plant 2 reporting coverage as a possible alternative explanation for a drop.')]

build=[
('h','Purpose of the build instructions'),('p','Deliver a credible, deterministic MVP while learning the workflow. Budget extra time for understanding, inspection and rehearsal. The experienced-team implementation may fit in about four focused hours; a learning-oriented team should reserve 8-10 hours plus buffer.'),
('h','Agent/team mission'),('p','Ship Solar Lens: a Streamlit dashboard that models expected plant-level mean AC power per reporting inverter, benchmarks the three required regressors on future time, and surfaces validation-calibrated residual candidates with data-coverage context.'),
('h','Working rules'),('b',['The official problem statement wins. This package documents choices, including plant-level aggregation, rather than inventing requirements.','Never call a deviation a fault. Use it as a lead for investigation.','Keep the final test interval untouched until champion and threshold are fixed.','Record every data-quality exclusion and n_reporting.','After each phase, report exactly: COMPLETED, BLOCKED, NEXT.']),
('h','Recommended project folder structure'),('p','solar-lens/\n  data/raw/ - supplied CSVs\n  src/ingest.py - timestamp and schema checks\n  src/intervals.py - mean AC and n_reporting\n  src/features.py - leakage-safe features\n  src/train.py - split, benchmark, selection and calibration\n  src/deviations.py - daylight gate and residual band\n  app/dashboard.py - Streamlit UI\n  artifacts/ - models, metrics, bands and predictions\n  tests/ - pipeline tests\n  README.md  requirements.txt  run_demo.sh'),
('h','Phased build plan'),('t',(['Phase','Learning budget','Deliverable'],[['1. Inspect and validate','60-90 min','Schema, timestamp, coverage and reporting-count report by plant.'],['2. Build interval table','75-105 min','15-minute mean AC per reporting inverter plus n_reporting and weather join.'],['3. Train benchmark','90-120 min','70/15/15 pipeline, three models, validation champion and frozen test.'],['4. Calibrate deviations','45-60 min','Validation residual band, daylight gate, test events and optional peer evidence.'],['5. Build dashboard','90-120 min','Streamlit charts, coverage labels, metrics and drilldown.'],['6. Test and rehearse','60-90 min','Clean run, edge tests and 3-5 minute demo.']],[43*mm,36*mm,85*mm])),
('page',''),('h','Critical implementation architecture pattern'),('p','Build one immutable PlantInterval table first. For each plant/timestamp, retain mean AC_POWER and n_reporting, then join weather. Build features from that table. Split in time order: first 70 percent train, next 15 percent validation, final 15 percent test. Fit preprocessing only on training. Pick champion using validation. Calculate the robust alert scale using the champion validation residuals. Freeze both model and band. Score test once. Save all split boundaries, feature names and calibration values with the artifact.'),
('h','Algorithms, model, data and integration notes'),('b',['Target: mean AC_POWER over reporting inverters. n_reporting is mandatory context. Do not sum AC as the primary target because a missing Plant 2 inverter can mimic a power drop.','Features: irradiation_value (unit not documented), ambient temperature, module temperature and hour sine/cosine. Do not use DC_POWER, yield columns or lagged actual output. Do not use day-of-year by default; compare it with the baseline on validation if time allows.','Linear Regression is the transparent baseline; Random Forest handles nonlinear response; SVR needs StandardScaler and a bounded search. Use the same rows and core features for all three.','Metrics: MAE, RMSE and R-squared on validation and final test. Choose on validation, present test once.','Daylight rule: use a small positive irradiation_value eligibility threshold documented in artifacts. Calculate robust scale from validation residuals. Display predicted mean AC plus/minus k times that validation-derived scale as a tolerance band, not model confidence.','Integration: Streamlit reads persisted artifacts directly. Do not spend hackathon time building FastAPI.']),
('h','Required test scenarios'),('t',(['Scenario','Expected result'],[['Mixed timestamps','Both formats normalize to the same 15-minute join key.'],['Incomplete inverter reporting','n_reporting falls; UI exposes coverage and does not treat it alone as a performance event.'],['Missing weather','No silent score; interval is excluded or explicitly marked coverage loss.'],['Leakage check','Scaler/model use training rows only; target lag, DC and yield never enter feature list.'],['Validation calibration','Band is derived from validation residuals, not in-sample training residuals.'],['Nighttime','Near-zero irradiation does not create a misleading underperformance event.'],['Synthetic residual','Test event has frozen band, n_reporting and complete weather/time context.']],[52*mm,112*mm])),
('page',''),('h','Dashboard/UI checklist'),('b',['Header explains: expected mean AC per reporting inverter; deviations are investigation candidates.','Plant and test-date filters; n_reporting/coverage badge or trend.','Metric cards: validation-selected champion, final test MAE, RMSE, R-squared, event count and weather coverage.','Model comparison table for Linear Regression, Random Forest and SVR.','Actual-versus-expected mean AC plot plus validation-derived tolerance band.','Residual plot with daylight eligibility and band; no "confidence interval" label.','Deviation table: time, actual, expected, residual, n_reporting, irradiation_value, temperature and neutral status.','Optional only: peer-inverter table or local review/severity note.']),
('h','Progress report after each phase'),('p','COMPLETED: [artifact or evidence produced]<br/>BLOCKED: [specific blocker, otherwise None]<br/>NEXT: [one immediate outcome]'),
('h','Definition of done'),('p','A clean environment runs the pipeline and starts Streamlit. The final test is separate from model selection and threshold calibration. All three required model metrics are displayed. Events carry n_reporting and weather context. The UI states unit uncertainty for irradiation and avoids fault claims. Tests cover time parsing, missing coverage, leakage, validation calibration and daylight gating.'),
('h','Final 3-5 minute demo script'),('b',['Open with the target and limitation: expected mean AC per reporting inverter, not a fault detector.','Show schema/coverage reasoning, including why n_reporting matters for Plant 2.','Show chronological 70/15/15 split and validation selection; then the final test model table.','Select a test day and compare actual versus expected with validation-derived tolerance band.','Open an event; read n_reporting, irradiation_value and temperatures. Optionally use inverter peers as supporting evidence.','Close: the output prioritizes investigation, but field evidence is required for fault conclusions.']),
('h','Common pitfalls and final instruction'),('p','Avoid random splitting, test-set champion selection, train-residual threshold calibration, summed target without coverage context, DC/yield/lag features, undocumented irradiation units, fake confidence intervals and premature FastAPI. Finish the repeatable benchmark and coverage-aware drilldown before optional peer evidence or review controls.')
]

make('01_Solar_Lens_Problem_Statement_Analysis.pdf','Solar Lens - Revised Problem Statement Analysis','A coverage-aware, time-safe solar-output prediction and deviation-triage MVP.',analysis)
